  /// Fills the current month's calendar for the demo student (STU-001) so
  /// the dashboard calendar and subject cards look alive on any day.
  static List<AttendanceModel> _buildCurrentMonthDemoAttendance() {
    final now = DateTime.now();
    final lastDay = DateTime(now.year, now.month + 1, 0).day;
    final courses = ['CS-001', 'CS-002', 'CS-005', 'CS-017'];
    final records = <AttendanceModel>[];
    for (var day = 1; day <= lastDay; day++) {
      for (var c = 0; c < courses.length; c++) {
        AttendanceStatus status = AttendanceStatus.present;
        // A little realistic variety: an occasional absent / half-day / leave.
        if (day % 7 == 0 && c == 0) {
          status = AttendanceStatus.absent;
        } else if (day % 9 == 0 && c == 1) {
          status = AttendanceStatus.halfDay;
        } else if (day % 11 == 0 && c == 2) {
          status = AttendanceStatus.leave;
        } else if (day % 13 == 0 && c == 3) {
          status = AttendanceStatus.absent;
        }
        records.add(AttendanceModel(
          id: 'ATT-CM-${now.month}-$day-$c',
          student: 'STU-001',
          studentName: 'Alex Smith',
          courseSchedule: courses[c],
          date: DateTime(now.year, now.month, day),
          status: status,
        ));
      }
    }
    return records;
  }

  // Instance getters forwarding to static data (needed by providers that access via instance)
  List<SchoolModel> get allSchools => demoSchools;
  List<InstructorModel> get allTeachers => demoTeachers;
  List<StudentModel> get allStudents => demoStudents;
  List<StudentGroupModel> get allClasses => demoClasses;
  List<CourseScheduleModel> get allCourseSchedules => demoCourseSchedules;
  List<AssignmentModel> get allAssignments => demoAssignments;
  List<AttendanceModel> get allAttendance => demoAttendance;

  // Demo Methods
  UserModel? login(String email, String password) {
    final userData = demoUsers[email];
    if (userData != null && userData['password'] == password) {
      return UserModel.fromJson(userData);
    }
    return null;
  }

  /// Registers a new student in demo mode and returns the created user, or
  /// null if the email is already registered.
  UserModel? signupStudent({
    required String fullName,
    required String email,
    required String password,
    int? age,
    String? gender,
    String? city,
    String? state,
    String? country,
    required String school,
    String? studentGroup,
  }) {
    final normalizedEmail = email.trim().toLowerCase();
    if (demoUsers.containsKey(normalizedEmail)) {
      return null;
    }

    final schoolInfo = demoSchools.firstWhere(
      (s) => s.id == school,
      orElse: () => demoSchools.first,
    );
    final group = studentGroup != null
        ? demoClasses.firstWhere(
            (g) => g.id == studentGroup,
            orElse: () => demoClasses.first,
          )
        : demoClasses.first;

    final nextRoll = demoStudents
            .where((s) => s.studentGroup == group.id)
            .length +
        1;
    final studentId = 'STU-${demoStudents.length + 100}';

    demoUsers[normalizedEmail] = {
      'name': studentId,
      'email': normalizedEmail,
      'full_name': fullName,
      'password': password,
      'role': 'student',
      'school': schoolInfo.id,
      'school_name': schoolInfo.name,
    };

    demoStudents.add(StudentModel(
      id: studentId,
      name: fullName,
      email: normalizedEmail,
      age: age,
      gender: gender,
      city: city,
      state: state,
      country: country,
      school: schoolInfo.id,
      schoolName: schoolInfo.name,
      studentGroup: group.id,
      studentGroupName: group.name,
      rollNumber: '$nextRoll',
    ));

    return UserModel.fromJson(demoUsers[normalizedEmail]!);
  }

  List<SchoolModel> searchSchools({String? state, String? city, String? query}) {
    var schools = List<SchoolModel>.from(demoSchools);
    
    if (state != null && state.isNotEmpty) {
      schools = schools.where((s) => s.state?.toLowerCase() == state.toLowerCase()).toList();
    }
    if (city != null && city.isNotEmpty) {
      schools = schools.where((s) => s.city?.toLowerCase() == city.toLowerCase()).toList();
    }
    if (query != null && query.isNotEmpty) {
      schools = schools.where((s) => s.name.toLowerCase().contains(query.toLowerCase())).toList();
    }
    
    return schools;
  }

  List<InstructorModel> getTeachers({String? school}) {
    var teachers = List<InstructorModel>.from(demoTeachers);
    if (school != null) {
      teachers = teachers.where((t) => t.school == school).toList();
    }
    return teachers;
  }

  List<StudentModel> getStudents({String? school, String? group}) {
    var students = List<StudentModel>.from(demoStudents);
    if (school != null) {
      students = students.where((s) => s.school == school).toList();
    }
    if (group != null) {
      students = students.where((s) => s.studentGroup == group).toList();
    }
    return students;
  }

  List<StudentGroupModel> getClasses({String? school}) {
    var classes = List<StudentGroupModel>.from(demoClasses);
    if (school != null) {
      classes = classes.where((c) => c.school == school).toList();
    }
    return classes;
  }

  List<CourseScheduleModel> getMyClasses(String instructorId) {
    return demoCourseSchedules.where((cs) => cs.instructor == instructorId).toList();
  }

  List<StudentModel> getClassStudents(String group) {
    return demoStudents.where((s) => s.studentGroup == group).toList();
  }

  AssignmentSubmissionModel? _findSubmission(String assignment, String studentId) {
    final subs = demoSubmissions
        .where((s) => s.assignment == assignment && s.student == studentId)
        .toList();
    return subs.isEmpty ? null : subs.first;
  }

  List<AssignmentModel> getMyAssignments(String group, {String? studentId}) {
    return demoAssignments.where((a) => a.studentGroup == group).map((a) {
      final submission = studentId != null ? _findSubmission(a.id, studentId) : null;
      return AssignmentModel(
        id: a.id,
        title: a.title,
        description: a.description,
        course: a.course,
        courseName: a.courseName,
        studentGroup: a.studentGroup,
        studentGroupName: a.studentGroupName,
        instructor: a.instructor,
        instructorName: a.instructorName,
        dueDate: a.dueDate,
        creation: a.creation,
        attachment: a.attachment,
        attachmentName: a.attachmentName,
        submitted: submission != null && submission.status != 'Returned',
        grade: submission?.grade,
        feedback: submission?.feedback,
        submissionStatus: submission?.status,
        submissionFile: submission?.file,
        submissionFileName: submission?.fileName,
        submittedAt: submission?.submittedAt,
      );
    }).toList();
  }

  bool submitAssignment({
    required String assignment,
    required String filePath,
    String? studentId,
  }) {
    final matches = demoAssignments.where((a) => a.id == assignment).toList();
    if (matches.isEmpty) {
      throw Exception('Assignment not found');
    }
    final assignmentModel = matches.first;

    // Returned submissions may be resubmitted (existing record is updated)
    final existing = studentId != null
        ? _findSubmission(assignment, studentId)
        : null;
    if (existing != null && existing.status != 'Returned') {
      throw Exception('You have already submitted this assignment');
    }

    // Mirror the backend: new submissions close after the due day ends,
    // but returned work can be resubmitted even past the deadline.
    if (existing == null && assignmentModel.isPastDeadline) {
      final due = assignmentModel.dueDate != null
          ? '${assignmentModel.dueDate!.year}-${assignmentModel.dueDate!.month.toString().padLeft(2, '0')}-${assignmentModel.dueDate!.day.toString().padLeft(2, '0')}'
          : 'unknown';
      throw Exception(
        'The submission deadline for this assignment has passed '
        '(was due on $due).',
      );
    }

    final fileName = filePath.split('/').last;
    final student = studentId != null
        ? demoStudents.where((s) => s.id == studentId).toList()
        : <StudentModel>[];
    final studentName = student.isNotEmpty ? student.first.name : 'Student';

    if (existing != null) {
      demoSubmissions[demoSubmissions.indexOf(existing)] =
          AssignmentSubmissionModel(
        id: existing.id,
        assignment: assignment,
        student: studentId,
        studentName: studentName,
        file: '/files/$fileName',
        fileName: fileName,
        submittedAt: DateTime.now(),
        status: 'Submitted',
      );
    } else {
      demoSubmissions.add(AssignmentSubmissionModel(
        id: 'SUB-${demoSubmissions.length + 100}',
        assignment: assignment,
        student: studentId,
        studentName: studentName,
        file: '/files/$fileName',
        fileName: fileName,
        submittedAt: DateTime.now(),
        status: 'Submitted',
      ));
    }
    return true;
  }

  List<AssignmentModel> getMyTeacherAssignments(String instructorId) {
    return demoAssignments.where((a) => a.instructor == instructorId).map((a) {
      final subs = demoSubmissions.where((s) => s.assignment == a.id).toList();
      final total = getClassStudents(a.studentGroup ?? '').length;
      return AssignmentModel(
        id: a.id,
        title: a.title,
        description: a.description,
        course: a.course,
        courseName: a.courseName,
        studentGroup: a.studentGroup,
        studentGroupName: a.studentGroupName,
        instructor: a.instructor,
        instructorName: a.instructorName,
        dueDate: a.dueDate,
        creation: a.creation,
        attachment: a.attachment,
        attachmentName: a.attachmentName,
        totalStudents: total,
        submittedCount: subs.length,
        gradedCount: subs.where((s) => s.isGraded).length,
      );
    }).toList();
  }

  AssignmentModel createAssignment({
    required String title,
    required String course,
    required String studentGroup,
    required DateTime dueDate,
    String? description,
    String? attachment,
    String? attachmentName,
    String? instructorId,
    String? instructorName,
  }) {
    final instructor = instructorId != null
        ? demoTeachers.firstWhere(
            (t) => t.id == instructorId,
            orElse: () => demoTeachers.first,
          )
        : demoTeachers.first;
    final group = demoClasses.firstWhere(
      (g) => g.id == studentGroup,
      orElse: () => demoClasses.first,
    );

    final assignment = AssignmentModel(
      id: 'ASG-${demoAssignments.length + 1000}',
      title: title,
      description: description,
      course: course,
      courseName: course,
      studentGroup: studentGroup,
      studentGroupName: group.name,
      instructor: instructor.id,
      instructorName: instructor.name,
      dueDate: dueDate,
      creation: DateTime.now(),
      attachment: attachment,
      attachmentName: attachmentName,
      totalStudents: getClassStudents(studentGroup).length,
    );
    demoAssignments.add(assignment);
    return assignment;
  }

  void updateAssignment({
    required String assignmentId,
    required String title,
    required String course,
    required String studentGroup,
    required DateTime dueDate,
    String? description,
    String? attachment,
    String? attachmentName,
    bool clearAttachment = false,
  }) {
    final index = demoAssignments.indexWhere((a) => a.id == assignmentId);
    if (index < 0) return;
    final old = demoAssignments[index];
    final group = demoClasses.firstWhere(
      (g) => g.id == studentGroup,
      orElse: () => demoClasses.first,
    );

    demoAssignments[index] = AssignmentModel(
      id: old.id,
      title: title,
      description: description,
      course: course,
      courseName: course,
      studentGroup: studentGroup,
      studentGroupName: group.name,
      instructor: old.instructor,
      instructorName: old.instructorName,
      dueDate: dueDate,
      creation: old.creation,
      attachment: clearAttachment ? null : (attachment ?? old.attachment),
      attachmentName:
          clearAttachment ? null : (attachmentName ?? old.attachmentName),
      totalStudents: getClassStudents(studentGroup).length,
    );
  }

  void deleteAssignment(String assignmentId) {
    demoAssignments.removeWhere((a) => a.id == assignmentId);
    demoSubmissions.removeWhere((s) => s.assignment == assignmentId);
  }

  List<AssignmentSubmissionModel> getAssignmentSubmissions(String assignment) {
    final students = demoStudents;
    return demoSubmissions.where((s) => s.assignment == assignment).map((s) {
      final student = students.where((st) => st.id == s.student).toList();
      return AssignmentSubmissionModel(
        id: s.id,
        assignment: s.assignment,
        student: s.student,
        studentName: student.isNotEmpty ? student.first.name : s.studentName,
        studentEmailId:
            student.isNotEmpty ? student.first.email : null,
        rollNumber: student.isNotEmpty ? student.first.rollNumber : null,
        file: s.file,
        fileName: s.fileName,
        submittedAt: s.submittedAt,
        grade: s.grade,
        feedback: s.feedback,
        status: s.status,
      );
    }).toList();
  }

  void unsubmitSubmission(String submission) {
    final index = demoSubmissions.indexWhere((s) => s.id == submission);
    if (index < 0) return;
    final old = demoSubmissions[index];
    demoSubmissions[index] = AssignmentSubmissionModel(
      id: old.id,
      assignment: old.assignment,
      student: old.student,
      studentName: old.studentName,
      file: old.file,
      fileName: old.fileName,
      submittedAt: old.submittedAt,
      status: 'Returned',
    );
  }

  void deleteSubmission(String submission) {
    demoSubmissions.removeWhere((s) => s.id == submission);
  }

  void gradeSubmission({
    required String submission,
    required double grade,
    String? feedback,
  }) {
    final index = demoSubmissions.indexWhere((s) => s.id == submission);
    if (index < 0) return;
    final old = demoSubmissions[index];
    demoSubmissions[index] = AssignmentSubmissionModel(
      id: old.id,
      assignment: old.assignment,
      student: old.student,
      studentName: old.studentName,
      file: old.file,
      fileName: old.fileName,
      submittedAt: old.submittedAt,
      grade: grade,
      feedback: feedback,
      status: 'Graded',
    );
  }

  List<InstructorModel> getTeachersWithClasses({String? school}) {
    final teachers = getTeachers(school: school);
    return teachers.map((t) {
      final classes = demoCourseSchedules
          .where((cs) => cs.instructor == t.id)
          .toList();
      return InstructorModel(
        id: t.id,
        name: t.name,
        email: t.email,
        phone: t.phone,
        school: t.school,
        department: t.department,
        designation: t.designation,
        classes: classes,
      );
    }).toList();
  }

  List<StudentGroupModel> getClassesWithStudents({String? school}) {
    return getClasses(school: school).map((c) {
      final students = getStudents(school: school, group: c.id);
      final enriched = students
          .map((s) => StudentModel(
                id: s.id,
                name: s.name,
                email: s.email,
                school: s.school,
                schoolName: s.schoolName,
                studentGroup: s.studentGroup,
                studentGroupName: s.studentGroupName,
                gender: s.gender,
                rollNumber: s.rollNumber,
              ))
          .toList();
      return StudentGroupModel(
        id: c.id,
        name: c.name,
        program: c.program,
        programName: c.programName,
        school: c.school,
        schoolName: c.schoolName,
        groupSize: enriched.length,
        active: c.active,
        students: enriched,
      );
    }).toList();
  }

  StudentDetailModel getStudentDetails(String studentId, {String? group}) {
    final student = demoStudents.firstWhere(
      (s) => s.id == studentId,
      orElse: () => demoStudents.first,
    );

    String? rollNumber = student.rollNumber;
    String groupName = student.studentGroupName ?? '';
    if (group != null) {
      final cls = demoClasses.where((c) => c.id == group).toList();
      if (cls.isNotEmpty) groupName = cls.first.name;
    }

    // Attendance summary
    final attendance =
        demoAttendance.where((a) => a.student == studentId).toList();
    final total = attendance.length;
    final present = attendance
        .where((a) =>
            a.status == AttendanceStatus.present ||
            a.status == AttendanceStatus.halfDay)
        .length;
    final overall = total > 0 ? (present / total * 100) : 0.0;

    final courseStats = <String, List<int>>{};
    for (final a in attendance) {
      final schedule =
          demoCourseSchedules.where((cs) => cs.id == a.courseSchedule).toList();
      final course =
          schedule.isNotEmpty ? (schedule.first.courseName ?? 'Unknown') : 'Unknown';
      courseStats.putIfAbsent(course, () => [0, 0]);
      courseStats[course]![1] += 1;
      if (a.status == AttendanceStatus.present ||
          a.status == AttendanceStatus.halfDay) {
        courseStats[course]![0] += 1;
      }
    }
    final courseWise = courseStats.map(
      (course, stats) =>
          MapEntry(course, stats[0] / stats[1] * 100),
    );

    // Grades
    final grades = <GradeRecord>[];
    for (final sub
        in demoSubmissions.where((s) => s.student == studentId)) {
      final assignments =
          demoAssignments.where((a) => a.id == sub.assignment).toList();
      final assignment = assignments.isNotEmpty ? assignments.first : null;
      if (group != null &&
          assignment != null &&
          assignment.studentGroup != group) {
        continue;
      }
      grades.add(GradeRecord(
        assignment: sub.assignment ?? '',
        title: assignment?.title ?? sub.assignment ?? '',
        courseName: assignment?.courseName,
        dueDate: assignment?.dueDate,
        grade: sub.grade,
        feedback: sub.feedback,
        status: sub.status,
      ));
    }
    grades.sort((a, b) =>
        (b.dueDate ?? DateTime(0)).compareTo(a.dueDate ?? DateTime(0)));

    return StudentDetailModel(
      id: student.id,
      name: student.name,
      email: student.email,
      gender: student.gender,
      school: student.school,
      schoolName: student.schoolName,
      studentGroup: group ?? student.studentGroup,
      studentGroupName: groupName,
      rollNumber: rollNumber,
      overallAttendance: overall,
      courseWiseAttendance: courseWise,
      grades: grades,
    );
  }

  AdminDashboardData getAdminDashboard({String? school}) {
    SchoolModel? schoolInfo;
    if (school != null) {
      final matches = demoSchools.where((s) => s.id == school).toList();
      if (matches.isNotEmpty) schoolInfo = matches.first;
    }

    return AdminDashboardData(
      school: schoolInfo,
      teachers: getTeachersWithClasses(school: school),
      students: getStudents(school: school),
      // Enriched classes so every page shows the same student counts
      classes: getClassesWithStudents(school: school),
    );
  }

  List<AttendanceModel> getStudentAttendance(String studentId) {
    return demoAttendance.where((a) => a.student == studentId).toList();
  }

  Map<String, double> getAttendanceSummary(String studentId) {
    final attendance = getStudentAttendance(studentId);
    final total = attendance.length;
    if (total == 0) return {'overall': 0};
    
    final present = attendance.where((a) => a.status == AttendanceStatus.present).length;
    final halfDay = attendance.where((a) => a.status == AttendanceStatus.halfDay).length;
    
    final percentage = ((present + (halfDay * 0.5)) / total) * 100;

    // Course-wise percentages for the dashboard subject cards.
    final courseWise = <String, double>{};
    final courseTotals = <String, int>{};
    final coursePresent = <String, int>{};
    for (final a in attendance) {
      final schedule = demoCourseSchedules
          .where((cs) => cs.id == a.courseSchedule)
          .toList();
      final course =
          schedule.isNotEmpty ? (schedule.first.courseName ?? 'Unknown') : 'Unknown';
      courseTotals[course] = (courseTotals[course] ?? 0) + 1;
      if (a.status == AttendanceStatus.present ||
          a.status == AttendanceStatus.halfDay) {
        coursePresent[course] = (coursePresent[course] ?? 0) + 1;
      }
    }
    courseTotals.forEach((course, count) {
      if (count > 0) {
        courseWise[course] = (coursePresent[course] ?? 0) / count * 100;
      }
    });

    return {
      'overall': percentage,
      ...courseWise,
    };
  }
}
